<label class="text-sm font-semibold">Question<input name="question" required maxlength="1000" class="mt-1 w-full rounded-lg border-gray-200"></label>
<label class="text-sm font-semibold">Answer type<select name="question_type" class="mt-1 w-full rounded-lg border-gray-200"><option value="single">Single choice</option><option value="multiple">Multiple choice</option><option value="open">Open answer (manual grading)</option></select></label>
<label class="text-sm font-semibold">Options, one per line (choice questions only)<textarea name="options" rows="4" class="mt-1 w-full rounded-lg border-gray-200" placeholder="First option&#10;Second option"></textarea></label>
<div class="grid gap-3 sm:grid-cols-2"><label class="text-sm font-semibold">Correct option number (single choice)<input name="correct_answer" type="number" min="1" max="6" class="mt-1 w-full rounded-lg border-gray-200" placeholder="1"></label><label class="text-sm font-semibold">Correct option numbers (multiple choice)<input name="correct_answers" class="mt-1 w-full rounded-lg border-gray-200" placeholder="1, 3"></label></div>
<p class="text-xs text-gray-500">For open answers, leave options and correct numbers empty. They are graded manually.</p>
